insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-08-07','opgelost','Offertes','Verzonden offerte zet de status nu ook in Bouw7 door',
   'Na het versturen van een offerte bleef het dossier soms op de oude substatus staan, in EVA en in Bouw7, zonder dat je dat zag: de melding meldde "verzonden" in het groen terwijl de status niet was bijgewerkt. Dat is verholpen. De status Verzonden gaat nu altijd door, ook als EVA en Bouw7 uit elkaar waren gelopen, en lukt het toch niet dan krijg je een duidelijke foutmelding in plaats van een groen vinkje. Staat de offerte al verder in het traject, bijvoorbeeld op Nabellen of Mondelinge toezegging, dan blijft die stand staan.'),
  ('2026-08-07','verbeterd','Dossiers','Substatus wijzigen loopt niet meer vast op Bouw7',
   'Stond er in Bouw7 een andere substatus dan in EVA, dan kon je de status niet meer wijzigen: je kreeg alleen de melding dat het daar zojuist was aangepast. Nu vraagt EVA wat je wilt: de stand uit Bouw7 overnemen, of jouw keuze toch doorzetten. Ook een wijziging via Opslaan op de Informatie-tab en via het afronden van een taak wordt voortaan naar Bouw7 teruggeschreven, zodat beide systemen gelijk blijven lopen.');
